PROCESSORS = {}


def register(name):
    def decorator(cls):
        PROCESSORS[name] = cls
        return cls
    return decorator


def create_processor(name, *args, **kwargs):
    if name not in PROCESSORS:
        raise KeyError(f'no processor registered for {name!r}')
    return PROCESSORS[name](*args, **kwargs)


@register('card')
class CardProcessor:
    def charge(self, amount):
        return f'charged {amount} via card'


@register('paypal')
class PaypalProcessor:
    def charge(self, amount):
        return f'charged {amount} via paypal'
